node -e "
const AdmZip = require('adm-zip');
const zip = new AdmZip('/workspace/testbed/docs/travel_summary.docx');
const docEntry = zip.getEntry('word/document.xml');
let xml = docEntry.getData().toString('utf8');

const oldText = 'Booking C4C633 | Maya Chen | SEA → SEA | economy | Status: confirmed | \$70';
const newText = 'Booking C4C633 | Maya Chen | SEA → SAN | economy | Status: on time | \$70';

if (!xml.includes(oldText)) { console.log('Old text not found!'); process.exit(1); }

xml = xml.replace(oldText, newText);
zip.updateFile('word/document.xml', Buffer.from(xml, 'utf8'));
zip.writeZip('/workspace/testbed/docs/travel_summary.docx');
console.log('File updated successfully!');
"
